import 'package:flutter/services.dart';

class MoneyInputFormatter extends TextInputFormatter {
  const MoneyInputFormatter();

  @override
  TextEditingValue formatEditUpdate(
    TextEditingValue oldValue,
    TextEditingValue newValue,
  ) {
    if (!newValue.composing.isCollapsed) {
      return newValue;
    }

    var input = newValue.text;
    // A grouping space is generated by us; deleting it should reach a digit.
    if (oldValue.selection.isCollapsed &&
        newValue.selection.isCollapsed &&
        oldValue.text.length == input.length + 1) {
      final oldCaret = oldValue.selection.extentOffset;
      final caret = newValue.selection.extentOffset;
      final backwards = oldCaret == caret + 1;
      if (caret >= 0 &&
          (backwards || oldCaret == caret) &&
          caret < oldValue.text.length &&
          oldValue.text[caret] == ' ' &&
          input == oldValue.text.replaceRange(caret, caret + 1, '')) {
        final digit = backwards ? caret - 1 : caret;
        if (digit >= 0 && digit < input.length) {
          input = input.replaceRange(digit, digit + 1, '');
          newValue = newValue.copyWith(
            selection: TextSelection.collapsed(offset: digit),
          );
        }
      }
    }
    final digits = input.replaceAll(RegExp(r'[^0-9]'), '');

    if (digits.isEmpty) {
      return const TextEditingValue(
        text: '',
        selection: TextSelection.collapsed(offset: 0),
      );
    }

    final formatted = digits.replaceAllMapped(
      RegExp(r'\B(?=(\d{3})+(?!\d))'),
      (_) => ' ',
    );

    int mapOffset(int offset) {
      if (offset < 0) return formatted.length;

      final safeOffset = offset.clamp(0, input.length);
      final digitsBefore = input
          .substring(0, safeOffset)
          .replaceAll(RegExp(r'[^0-9]'), '')
          .length;

      if (digitsBefore == 0) return 0;

      var count = 0;
      for (var i = 0; i < formatted.length; i++) {
        if (formatted.codeUnitAt(i) >= 48 && formatted.codeUnitAt(i) <= 57) {
          count++;
        }
        if (count == digitsBefore) {
          return i + 1;
        }
      }
      return formatted.length;
    }

    return TextEditingValue(
      text: formatted,
      selection: TextSelection(
        baseOffset: mapOffset(newValue.selection.baseOffset),
        extentOffset: mapOffset(newValue.selection.extentOffset),
        affinity: newValue.selection.affinity,
        isDirectional: newValue.selection.isDirectional,
      ),
    );
  }
}
